package com.franco.desco.adapter.out.sqlserver.inventory;

import com.franco.desco.adapter.out.sqlserver.shared.*;
import com.franco.desco.application.inventory.InventoryCommands.*;
import com.franco.desco.application.inventory.port.out.InventoryPersistencePort;
import com.franco.desco.application.shared.*;
import com.franco.desco.application.shared.pagination.PageResult;
import com.franco.desco.domain.inventory.InventoryModels;
import org.springframework.jdbc.core.simple.SimpleJdbcCall;
import org.springframework.stereotype.Component;
import java.util.*;

@Component
public class InventorySqlServerAdapter implements InventoryPersistencePort {
    private final SqlServerPaExecutor e; private final PaPayloadFactory f;
    private final SimpleJdbcCall listAssets,getAsset,createAsset,updateAsset,retireAsset,registerVehicle,updateMileage,listSupplies,createSupply,updateSupply,kardex,adjustSupply;
    public InventorySqlServerAdapter(SqlServerPaFactory x,SqlServerPaExecutor e,PaPayloadFactory f){this.e=e;this.f=f;listAssets=x.callWithResultSets("logistica","PA_BienInventario_Sel_Listado","items");getAsset=x.callWithResultSets("logistica","PA_BienInventario_Sel_Detalle","bien","recursos","movimientos");createAsset=x.call("logistica","PA_BienInventario_Ins_Registro");updateAsset=x.call("logistica","PA_BienInventario_Upd_Registro");retireAsset=x.call("logistica","PA_BienInventario_Upd_Baja");registerVehicle=x.call("logistica","PA_Vehiculo_Ins_Registro");updateMileage=x.call("logistica","PA_Vehiculo_Upd_Kilometraje");listSupplies=x.callWithResultSets("logistica","PA_Suministro_Sel_Listado","items");createSupply=x.call("logistica","PA_Suministro_Ins_Registro");updateSupply=x.call("logistica","PA_Suministro_Upd_Registro");kardex=x.callWithResultSets("logistica","PA_SuministroMovimiento_Sel_Kardex","items");adjustSupply=x.call("logistica","PA_SuministroMovimiento_Ins_Ajuste");}

    public PersistenceResult<PageResult<InventoryModels.AssetSummary>> listAssets(ListAssets c,SessionIdentity i,RequestMetadata m){int p=c.page().pagina(),s=c.page().tamanio();AssetFilter z=c.page().filtros();var filters=map("empresaId",z==null?null:z.empresaId(),"tipoBienId",z==null?null:z.tipoBienId(),"estadoBien",z==null?null:z.estadoBien(),"pagina",p,"tamanoPagina",s);var rs=e.executeJsonMultiResult(listAssets,f.forQuery(i,m,Map.of("filtros",filters)));return PaAdapterSupport.page(rs.raw(),rs.rows("items"),p,s,this::asset,"No se pudo consultar el inventario.");}
    public PersistenceResult<InventoryModels.AssetDetail> getAsset(GetAsset c,SessionIdentity i,RequestMetadata m){var rs=e.executeJsonMultiResult(getAsset,f.forQuery(i,m,Map.of("bien",Map.of("bienInventarioId",c.bienInventarioId()))));if(!PaAdapterSupport.success(rs.raw()))return PersistenceResult.error(PaAdapterSupport.message(rs.raw(),"No se pudo consultar el bien."));var r=rs.one("bien").orElse(null);if(r==null)return PersistenceResult.error("El bien seleccionado no está disponible.");var resources=rs.rows("recursos").stream().map(x->new InventoryModels.Resource(SqlValues.longValue(x,"recursoProgramadoId"),SqlValues.string(x,"estadoProceso"),SqlValues.decimal(x,"cantidadProgramada"),SqlValues.instant(x,"fechaProgramacion"),SqlValues.longValue(x,"campaniaVentaId"),SqlValues.longValue(x,"operativoVentaId"),SqlValues.longValue(x,"salidaCampoId"))).toList();var movements=rs.rows("movimientos").stream().map(x->new InventoryModels.Movement(SqlValues.longValue(x,"recursoMovimientoId"),SqlValues.string(x,"tipoMovimiento"),SqlValues.decimal(x,"cantidad"),SqlValues.instant(x,"fechaHora"),SqlValues.string(x,"observacion"))).toList();return PersistenceResult.ok(PaAdapterSupport.message(rs.raw(),"Bien consultado correctamente."),new InventoryModels.AssetDetail(SqlValues.longValue(r,"bien_inventario_id"),SqlValues.longValue(r,"empresa_id"),SqlValues.string(r,"empresa"),SqlValues.longValue(r,"tipo_bien_id"),SqlValues.string(r,"tipoBien"),SqlValues.string(r,"codigo_patrimonial"),SqlValues.string(r,"nombre"),SqlValues.string(r,"marca"),SqlValues.string(r,"modelo"),SqlValues.string(r,"serie"),SqlValues.string(r,"estado_bien"),SqlValues.bool(r,"estado"),SqlValues.string(r,"placa"),SqlValues.string(r,"tipoVehiculo"),SqlValues.decimal(r,"kilometrajeKm"),resources,movements));}
    public PersistenceResult<Long> createAsset(CreateAsset c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(createAsset,f.forWrite(i,m,c,Map.of("bien",map("empresaId",c.empresaId(),"tipoBienId",c.tipoBienId(),"codigoPatrimonial",c.codigoPatrimonial(),"nombre",c.nombre(),"marca",c.marca(),"modelo",c.modelo(),"serie",c.serie()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nBienInventarioId"),"No se pudo registrar el bien.");}
    public PersistenceResult<Void> updateAsset(UpdateAsset c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(updateAsset,f.forWrite(i,m,c,Map.of("bien",map("bienInventarioId",c.bienInventarioId(),"nombre",c.nombre(),"marca",c.marca(),"modelo",c.modelo(),"serie",c.serie(),"estadoBien",c.estadoBien()))));return PaAdapterSupport.result(out,null,"No se pudo actualizar el bien.");}
    public PersistenceResult<Void> retireAsset(RetireAsset c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(retireAsset,f.forWrite(i,m,c,Map.of("bien",map("bienInventarioId",c.bienInventarioId(),"motivo",c.motivo()))));return PaAdapterSupport.result(out,null,"No se pudo dar de baja el bien.");}
    public PersistenceResult<Long> registerVehicle(RegisterVehicle c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(registerVehicle,f.forWrite(i,m,c,Map.of("vehiculo",map("bienInventarioId",c.bienInventarioId(),"placa",c.placa(),"tipoVehiculo",c.tipoVehiculo(),"kilometrajeKm",c.kilometrajeKm()))));Long id=SqlValues.longValue(out,"nVehiculoId");if(id==null)id=c.bienInventarioId();return PaAdapterSupport.result(out,id,"No se pudo registrar el vehículo.");}
    public PersistenceResult<Void> updateMileage(UpdateMileage c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(updateMileage,f.forWrite(i,m,c,Map.of("vehiculo",map("vehiculoId",c.vehiculoId(),"kilometrajeKm",c.kilometrajeKm()))));return PaAdapterSupport.result(out,null,"No se pudo actualizar el kilometraje.");}
    public PersistenceResult<PageResult<InventoryModels.Supply>> listSupplies(ListSupplies c,SessionIdentity i,RequestMetadata m){int p=c.page().pagina(),s=c.page().tamanio();var filters=map("pagina",p,"tamanoPagina",s);var rs=e.executeJsonMultiResult(listSupplies,f.forQuery(i,m,Map.of("filtros",filters)));return PaAdapterSupport.page(rs.raw(),rs.rows("items"),p,s,this::supply,"No se pudieron consultar los suministros.");}
    public PersistenceResult<Long> createSupply(CreateSupply c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(createSupply,f.forWrite(i,m,c,Map.of("suministro",map("codigo",c.codigo(),"nombre",c.nombre(),"unidadMedida",c.unidadMedida(),"stockInicial",c.stockInicial()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nSuministroId"),"No se pudo registrar el suministro.");}
    public PersistenceResult<Void> updateSupply(UpdateSupply c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(updateSupply,f.forWrite(i,m,c,Map.of("suministro",map("suministroId",c.suministroId(),"nombre",c.nombre(),"unidadMedida",c.unidadMedida()))));return PaAdapterSupport.result(out,null,"No se pudo actualizar el suministro.");}
    public PersistenceResult<List<InventoryModels.SupplyMovement>> supplyMovements(ListSupplyMovements c,SessionIdentity i,RequestMetadata m){Map<String,Object> filters=map("suministroId",c.suministroId());var rs=e.executeJsonMultiResult(kardex,f.forQuery(i,m,Map.of("filtros",filters)));if(!PaAdapterSupport.success(rs.raw()))return PersistenceResult.error(PaAdapterSupport.message(rs.raw(),"No se pudo consultar el kardex."));return PersistenceResult.ok(PaAdapterSupport.message(rs.raw(),"Kardex consultado correctamente."),rs.rows("items").stream().map(this::supplyMovement).toList());}
    public PersistenceResult<Long> adjustSupply(AdjustSupply c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(adjustSupply,f.forWrite(i,m,c,Map.of("movimiento",map("suministroId",c.suministroId(),"tipoMovimiento",c.tipoMovimiento(),"cantidad",c.cantidad(),"documentoReferencia",c.documentoReferencia(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nSuministroMovimientoId"),"No se pudo registrar el movimiento de suministro.");}
    private InventoryModels.AssetSummary asset(Map<String,Object>r){return new InventoryModels.AssetSummary(SqlValues.longValue(r,"bienInventarioId"),SqlValues.longValue(r,"empresaId"),SqlValues.string(r,"empresa"),SqlValues.longValue(r,"tipoBienId"),SqlValues.string(r,"tipoBien"),SqlValues.string(r,"codigoPatrimonial"),SqlValues.string(r,"nombre"),SqlValues.string(r,"marca"),SqlValues.string(r,"modelo"),SqlValues.string(r,"serie"),SqlValues.string(r,"estadoBien"),SqlValues.bool(r,"esVehiculo"),SqlValues.string(r,"placa"),SqlValues.string(r,"tipoVehiculo"),SqlValues.decimal(r,"kilometrajeKm"));}
    private InventoryModels.Supply supply(Map<String,Object>r){return new InventoryModels.Supply(SqlValues.longValue(r,"suministroId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.string(r,"unidadMedida"),SqlValues.bool(r,"estado"),SqlValues.decimal(r,"stock"));}
    private InventoryModels.SupplyMovement supplyMovement(Map<String,Object>r){return new InventoryModels.SupplyMovement(SqlValues.longValue(r,"suministroMovimientoId"),SqlValues.longValue(r,"suministroId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.string(r,"unidadMedida"),SqlValues.longValue(r,"recursoProgramadoId"),SqlValues.string(r,"tipoMovimiento"),SqlValues.decimal(r,"cantidad"),SqlValues.instant(r,"fechaHora"),SqlValues.string(r,"documentoReferencia"),SqlValues.string(r,"observacion"),SqlValues.string(r,"usuario"));}
    private static Map<String,Object>map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int x=0;x<p.length;x+=2)if(p[x+1]!=null)m.put((String)p[x],p[x+1]);return m;}
}
